+		return "Inferred work on " + strings.ReplaceAll(activity.Branch, "-", " ")
+	}
+	if len(activity.ChangedFiles) == 1 {
+		return "Inferred work on " + activity.ChangedFiles[0]
+	}
+	if len(activity.ChangedFiles) > 1 {
