+func jsonConfigHasHookCommand(path, hookPath, command string) bool {
+	data, err := os.ReadFile(path)
+	if err != nil || !gjson.ValidBytes(data) {
+		return false
+	}
+	entries := gjson.GetBytes(data, hookPath)
+	if !entries.IsArray() {
+		return false
+	}
+	for _, entry := range entries.Array() {
+		for _, hook := range entry.Get("hooks").Array() {
+			if hook.Get("command").String() == command {
+				return true
+			}
+		}
+	}
+	return false
+}
+
+func readJSONConfigOrEmpty(path string) ([]byte, bool, error) {
+	data, err := os.ReadFile(path)
+	if os.IsNotExist(err) {
+		return []byte("{}"), false, nil
+	}
+	if err != nil {
+		return nil, false, err
+	}
+	return data, true, nil
+}
+
+func ensureOneTimeBackup(path string) (string, error) {
+	backupPath := path + ".taskpilot.bak"
+	if _, err := os.Stat(backupPath); err == nil {
+		return backupPath, nil
+	} else if !os.IsNotExist(err) {
+		return "", err
+	}
+	if err := copyFile(path, backupPath); err != nil {
+		return "", err
+	}
+	return backupPath, nil
+}
+
+func atomicWriteFile(path string, data []byte, perm os.FileMode) error {
+	dir := filepath.Dir(path)
+	if err := ensureDir(dir); err != nil {
+		return err
+	}
+	tmp, err := os.CreateTemp(dir, "."+filepath.Base(path)+".tmp-*")
+	if err != nil {
+		return err
+	}
+	tmpPath := tmp.Name()
+	cleanup := true
+	defer func() {
+		if cleanup {
+			_ = os.Remove(tmpPath)
+		}
+	}()
+	if _, err := tmp.Write(data); err != nil {
+		_ = tmp.Close()
+		return err
+	}
+	if err := tmp.Chmod(perm); err != nil {
+		_ = tmp.Close()
+		return err
+	}
+	if err := tmp.Sync(); err != nil {
+		_ = tmp.Close()
+		return err
+	}
+	if err := tmp.Close(); err != nil {
+		return err
+	}
+	if err := os.Rename(tmpPath, path); err != nil {
+		return err
+	}
+	cleanup = false
+	if d, err := os.Open(dir); err == nil {
+		_ = d.Sync()
+		_ = d.Close()
+	}
+	return nil
