	}
	return repoActivity{
		Config:       cfg,
		Branch:       gitBranch(root),
		Commit:       gitCommit(root),
		ChangedFiles: gitChangedFileListIn(root),
	}, nil
}

func inferredTaskTitle(activity repoActivity) string {
