		payload.MatchScore = match.Score
		payload.MatchReasons = match.Reasons
	}
	tasks, err := tasksForProject(activity.Config.ProjectID)
	if err != nil {
		payload.Warnings = append(payload.Warnings, "Could not load tasks: "+err.Error())
