		}
		return print(out, *jsonOut)
	case "list":
		fs := flag.NewFlagSet("repo list", flag.ExitOnError)
		project := fs.String("project", "", "project id")
		jsonOut := fs.Bool("json", false, "print JSON")
		_ = fs.Parse(args[1:])
		path := "/api/repositories"
