func queuedHandoffCheckpointPaths() ([]string, error) {
	dir := handoffOutboxDir()
	entries, err := os.ReadDir(dir)
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	paths := []string{}
